using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Windows.Forms;
internal static class Program
{
 [STAThread] private static int Main(string[] args)
 {
  if (args.Contains("--deliberate-failure")) { Console.Error.WriteLine("EXPECTED_NEGATIVE_CONTROL: deliberately failing assertion"); return 7; }
  var passed = new List<string>();
  void Check(string name, bool condition) { if (!condition) throw new Exception(name); passed.Add(name); }
  try
  {
   Check("managed_arithmetic", Enumerable.Range(1, 100).Sum() == 5050);
   var a = new Random(29); var b = new Random(29);
   Check("seeded_runtime_random", Enumerable.Range(0, 100).All(_ => a.Next() == b.Next()));
   Check("x64_runtime", Environment.Is64BitProcess);
   using (var bitmap = new Bitmap(8, 8))
   {
    using (var graphics = Graphics.FromImage(bitmap)) { graphics.Clear(Color.Red); graphics.FillRectangle(Brushes.Blue, 4, 0, 4, 8); }
    Check("gdi_pixel_assertions", bitmap.GetPixel(0, 0).ToArgb() == Color.Red.ToArgb() && bitmap.GetPixel(7, 7).ToArgb() == Color.Blue.ToArgb());
    using var stream = new MemoryStream(); bitmap.Save(stream, ImageFormat.Png); stream.Position = 0;
    using var decoded = new Bitmap(stream);
    Check("png_round_trip", decoded.Width == 8 && decoded.Height == 8 && decoded.GetPixel(7, 7).ToArgb() == Color.Blue.ToArgb());
   }
   using (var panel = new Panel { Size = new Size(8, 8), BackColor = Color.Green })
   using (var output = new Bitmap(8, 8))
   {
    panel.DrawToBitmap(output, new Rectangle(0, 0, 8, 8));
    Check("winforms_offscreen_render", output.GetPixel(4, 4).ToArgb() == Color.Green.ToArgb());
   }
   Console.WriteLine(JsonSerializer.Serialize(new { status = "PASS", runtime = Environment.Version.ToString(), architecture = RuntimeInformation.ProcessArchitecture.ToString(), tests = passed }));
   return 0;
  }
  catch (Exception error) { Console.Error.WriteLine(JsonSerializer.Serialize(new { status = "FAIL", passed, error = error.ToString() })); return 1; }
 }
}

